"""Per-dataset, per-extractor measured resource dashboard; no live/fake data."""
from pathlib import Path
import json,re,statistics
from pilot import ROOT

env=json.loads((ROOT/'outputs/environment.json').read_text());cores=env['logical_cpus'];data={}
for name in ['REHAB26','QEVD','Pose-Estimation-Model-Comparison']:
 data[name]={}
 for model in ['lite','full','heavy']:
  if name=='REHAB26':run=ROOT/'outputs/correction/gpu'/model;log=run.parent/(model+'.log')
  else:run=ROOT/'outputs/resource-check'/name/'gpu'/model;log=run.parent.parent/(model+'.log')
  series=json.loads((run/'resources.json').read_text());metric=json.loads((run/name/'metrics.json').read_text());assert series
  assert 'renderer: NVIDIA GeForce RTX 3050 Ti' in log.read_text()
  t0=series[0]['time'];points=[]
  for s in series:
   try:g,v=map(float,s['whole_gpu_util_memory'].split(','))
   except ValueError:continue
   points.append({'seconds':round(s['time']-t0,3),'cpu_pct':round(s['process_cpu_pct_one_core']/cores,3),'system_cpu_pct':s['system_cpu_pct'],'ram_mib':round(s['process_rss_mb'],2),'gpu_pct':g,'vram_mib':v})
  assert points
  data[name][model]={'cpu_mean_pct_machine':metric['process_cpu_pct_one_core_mean']/cores,'cpu_mean_pct_one_core':metric['process_cpu_pct_one_core_mean'],'cpu_peak_pct_machine':max(x['cpu_pct'] for x in points),'ram_peak_mib':max(x['ram_mib'] for x in points),'gpu_peak_pct_device':max(x['gpu_pct'] for x in points),'gpu_mean_pct_device':statistics.mean(x['gpu_pct'] for x in points),'vram_peak_mib_device':max(x['vram_mib'] for x in points),'pose_mean_ms':metric['pose_mean_ms'],'pose_p95_ms':metric['pose_p95_ms'],'sample_count':len(points),'sample_span_seconds':points[-1]['seconds'],'frames':metric['frames'],'points':points,'source':str((run/'resources.json').relative_to(ROOT)),'measurement_note':'REHAB26은 교정 시연용 51초 영상의 추출 기록. 다른 두 자료는 같은 샘플을 별도 프로세스에서 재측정한 자원 기록.'}
payload={'datasets':data,'hardware':{'cpu':'Intel Core i7-12700H','logical_cpus':cores,'ram_gib':env['ram_bytes']/2**30,'gpu':'RTX 3050 Ti Laptop','vram_mib':4096},'date':'2026-10-16','scope':'포즈 추출·전처리·그리기·영상/좌표 저장 실행 기록. 교정 분류기 학습·브라우저 재생 자원 측정은 별도이며 여기 포함하지 않음. GPU/VRAM은 데스크톱 등 다른 프로세스 포함한 장치 전체 측정.'}
(ROOT/'correction/resource-dashboard.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2))
section='''<section id="resource-dashboard" class="resource-section"><div class="res-title"><div><span class="eyebrow">MEASURED PERFORMANCE</span><h2>실행 자원 사용량</h2><p id="res-context" class="muted"></p></div><span class="res-badge">● 저장된 실측 기록</span></div><div class="hardware"><span>i7-12700H · 20스레드</span><span>RAM 약 16GB</span><span>RTX 3050 Ti · 4GB</span><span>2026.10.16</span></div><div id="res-cards" class="res-cards"></div><div class="res-charts"><div class="chart-panel"><h3>처리 중 사용률 변화</h3><div class="legend"><span class="cpu-dot">프로세스 CPU · 전체 코어 기준</span><span class="gpu-dot">NVIDIA GPU · 장치 전체</span></div><div id="res-util"></div></div><div class="chart-panel"><h3>메모리 사용량 변화</h3><div class="legend"><span class="ram-dot">프로세스 RAM</span><span class="vram-dot">NVIDIA VRAM · 장치 전체</span></div><div id="res-memory"></div></div></div><div class="chart-panel compare-panel"><div class="compare-title"><h3>같은 데이터셋 · 모델 3종 비교</h3><label>비교 항목 <select id="resource-metric"><option value="pose_mean_ms">평균 관절 추론 시간</option><option value="ram_peak_mib">최대 프로세스 RAM</option><option value="cpu_mean_pct_machine">평균 프로세스 CPU</option></select></label></div><div id="res-bars"></div><div class="table-scroll"><table><thead><tr><th>모델</th><th>추론 평균</th><th>CPU 평균</th><th>RAM 최대</th><th>GPU 최대</th><th>VRAM 최대</th></tr></thead><tbody id="res-table"></tbody></table></div></div><div class="res-foot"><p id="res-sampling"></p><p>CPU 100%는 논리 코어 20개 전체를 사용한 기준입니다. RAM은 추출 프로세스의 RSS이며, GPU·VRAM은 다른 앱을 포함한 NVIDIA 장치 전체 값입니다.</p><p>약 0.5초 간격으로 기록했으며 짧은 순간의 최대치는 놓칠 수 있습니다. 그래프의 가로축은 영상 재생 시간이 아닌 처리 경과 시간입니다. 실시간 모니터링 화면이 아닙니다.</p><p>측정 범위: 관절 추출·전처리·그리기·결과 저장. 정상·오류 분류기 학습 및 이 화면의 재생 자원은 포함하지 않습니다. <a id="res-raw">선택한 원본 측정 기록</a> · <a href="correction/resource-dashboard.json">전체 측정 요약</a></p></div></section>'''
css='''
.resource-section{background:linear-gradient(145deg,#182c38,#17232f);border:1px solid #304957;padding:28px;box-shadow:0 18px 45px #0002}.res-title{display:flex;justify-content:space-between;align-items:center;gap:12px}.eyebrow{font-size:11px;letter-spacing:2.6px;color:#6ed7c7;font-weight:750}.res-title h2{font-size:25px;margin:7px 0}.res-title p{font-size:14px}.res-badge{white-space:nowrap;border:1px solid #3d605d;border-radius:30px;padding:7px 12px;background:#23423e;color:#9cebd0;font-size:12px}.hardware{display:flex;gap:9px;flex-wrap:wrap;margin:14px 0 22px}.hardware span{border:1px solid #344d5c;border-radius:6px;padding:6px 10px;font-size:12px;color:#c2d2df;background:#1c303e}.res-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.res-card{border:1px solid #36505d;background:#1b303d;border-radius:12px;padding:18px;position:relative;overflow:hidden}.res-card:before{content:'';position:absolute;top:0;left:0;width:100%;height:3px;background:var(--accent)}.res-card .res-label{font-size:13px;color:#c3d1dc}.res-value{font-size:31px;font-weight:750;letter-spacing:-1px;margin:12px 0 5px;font-variant-numeric:tabular-nums}.res-value span{font-size:15px;color:#a5bfce;letter-spacing:0;margin-left:5px}.res-card small{font-size:11px;color:#9fb7c7}.res-meter{height:4px;border-radius:4px;background:#0f202c;margin-top:14px;overflow:hidden}.res-meter i{display:block;height:100%;background:var(--accent);border-radius:4px}.res-charts{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:20px}.chart-panel{border:1px solid #304957;border-radius:12px;background:#152733;padding:18px;min-width:0}.chart-panel h3{font-size:15px;margin:0 0 14px}.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:10px;color:#b9cbd7;margin-bottom:10px}.legend span:before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px}.cpu-dot:before{background:#69d9cd}.gpu-dot:before{background:#b49bf3}.ram-dot:before{background:#80b6fa}.vram-dot:before{background:#f3bf77}.resource-section svg{width:100%;height:auto;display:block;overflow:visible}.compare-panel{margin-top:16px}.compare-title{display:flex;justify-content:space-between;align-items:center;gap:12px}.compare-title label{font-size:12px;color:#bdd1dd}.compare-title select{font-size:12px;padding:7px;margin-left:5px}#res-bars{margin:14px 0 20px}.bar-row{display:grid;grid-template-columns:60px 1fr 104px;gap:15px;align-items:center;font-size:13px;margin:14px 0;color:#c2d5df}.bar-track{height:17px;background:#0b1d28;border-radius:5px;overflow:hidden}.bar-fill{height:100%;background:var(--bar);border-radius:5px;transition:width .35s}.bar-row.is-selected{color:#fff;font-weight:700}.bar-value{text-align:right;font-variant-numeric:tabular-nums}.table-scroll{overflow-x:auto}.resource-section table{font-size:12px;white-space:nowrap}.resource-section th{color:#91adbd;font-weight:500}.resource-section td{font-variant-numeric:tabular-nums}.resource-section tr.selected-model{background:#254151}.model-chip{display:inline-flex;align-items:center;gap:7px}.model-chip:before{content:'';width:7px;height:7px;border-radius:50%;background:var(--chip)}.res-foot{font-size:11px;color:#9cb6c7;line-height:1.75;margin-top:18px}.res-foot p{margin:6px 0}@media(max-width:1000px){.res-cards{grid-template-columns:1fr 1fr}.res-charts{grid-template-columns:1fr}}@media(max-width:600px){.res-title,.compare-title{align-items:flex-start;flex-direction:column}.resource-section{padding:16px}.res-value{font-size:27px}.res-cards{gap:8px}.res-card{padding:13px}.legend{font-size:9px}.bar-row{grid-template-columns:46px 1fr 83px;gap:8px;font-size:12px}}
'''
js='''const RESOURCE=__DATA__;const palette={lite:'#69d9cd',full:'#80b6fa',heavy:'#b49bf3'};const svgNS='http://www.w3.org/2000/svg';function lineChart(points,keys,colors,unit,ceiling,title){const W=500,H=220,L=46,R=15,T=12,B=35,span=Math.max(1,points.at(-1).seconds),max=ceiling||Math.max(1,...points.flatMap(p=>keys.map(k=>p[k])))*1.15;const x=t=>L+t/span*(W-L-R),y=v=>H-B-v/max*(H-T-B);let svg='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+title+'">';for(let i=0;i<=4;i++){const v=max*i/4,yy=y(v);svg+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+yy+'" y2="'+yy+'" stroke="#304652" stroke-dasharray="3 5"/><text x="'+(L-8)+'" y="'+(yy+4)+'" text-anchor="end" fill="#93afc0" font-size="10">'+v.toFixed(max>100?0:0)+'</text>'}for(let i=0;i<=4;i++){const t=span*i/4;svg+='<text x="'+x(t)+'" y="'+(H-13)+'" text-anchor="middle" fill="#93afc0" font-size="10">'+t.toFixed(1)+'s</text>'}keys.forEach((key,i)=>{const path=points.map((p,j)=>(j?'L':'M')+x(p.seconds).toFixed(2)+','+y(p[key]).toFixed(2)).join(' ');svg+='<path d="'+path+'" fill="none" stroke="'+colors[i]+'" stroke-width="2.3" stroke-linejoin="round" stroke-linecap="round"/>';for(const p of points){svg+='<circle cx="'+x(p.seconds)+'" cy="'+y(p[key])+'" r="3" aria-hidden="true" fill="'+colors[i]+'" opacity="0"><title>'+key+': '+p[key].toFixed(1)+' '+unit+' / '+p.seconds.toFixed(1)+'s</title></circle>'}});return svg+'</svg>'}function renderResources(){const ds=dataset.value,m=model.value,all=RESOURCE.datasets[ds],r=all[m];document.querySelector('#res-context').textContent=DATA.datasets[ds].title+' / '+m.toUpperCase()+' · 선택에 따라 아래 실측 기록이 바뀝니다.';const cards=[{label:'프로세스 CPU · 평균',value:r.cpu_mean_pct_machine.toFixed(1),unit:'%',sub:'20개 전체 코어 기준 · 순간 최대 '+r.cpu_peak_pct_machine.toFixed(1)+'%',color:'#69d9cd',ratio:r.cpu_mean_pct_machine},{label:'프로세스 RAM · 최대',value:r.ram_peak_mib.toFixed(0),unit:'MiB',sub:'관절 추출 프로세스의 물리 메모리',color:'#80b6fa',ratio:r.ram_peak_mib/(RESOURCE.hardware.ram_gib*1024)*100},{label:'NVIDIA GPU · 최대',value:r.gpu_peak_pct_device.toFixed(0),unit:'%',sub:'장치 전체 · 평균 '+r.gpu_mean_pct_device.toFixed(1)+'%',color:'#b49bf3',ratio:r.gpu_peak_pct_device},{label:'NVIDIA VRAM · 최대',value:r.vram_peak_mib_device.toFixed(0),unit:'MiB',sub:'장치 전체 / 4,096 MiB',color:'#f3bf77',ratio:r.vram_peak_mib_device/4096*100}];document.querySelector('#res-cards').innerHTML=cards.map(c=>'<div class="res-card" style="--accent:'+c.color+'"><div class="res-label">'+c.label+'</div><div class="res-value">'+c.value+'<span>'+c.unit+'</span></div><small>'+c.sub+'</small><div class="res-meter"><i style="width:'+Math.max(0,Math.min(100,c.ratio))+'%"></i></div></div>').join('');document.querySelector('#res-util').innerHTML=lineChart(r.points,['cpu_pct','gpu_pct'],['#69d9cd','#b49bf3'],'%',100,'처리 시간에 따른 CPU와 NVIDIA GPU 사용률');document.querySelector('#res-memory').innerHTML=lineChart(r.points,['ram_mib','vram_mib'],['#80b6fa','#f3bf77'],'MiB',null,'처리 시간에 따른 프로세스 RAM과 NVIDIA VRAM');const key=document.querySelector('#resource-metric').value,unit=key==='pose_mean_ms'?'ms':key==='ram_peak_mib'?'MiB':'%',max=Math.max(...Object.values(all).map(x=>x[key]));document.querySelector('#res-bars').innerHTML=['lite','full','heavy'].map(k=>'<div class="bar-row '+(k===m?'is-selected':'')+'"><span>'+k.toUpperCase()+'</span><div class="bar-track"><div class="bar-fill" style="--bar:'+palette[k]+';width:'+(all[k][key]/max*100)+'%"></div></div><span class="bar-value">'+all[k][key].toFixed(1)+' '+unit+'</span></div>').join('');document.querySelector('#res-table').innerHTML=['lite','full','heavy'].map(k=>{const a=all[k];return '<tr class="'+(k===m?'selected-model':'')+'"><td><span class="model-chip" style="--chip:'+palette[k]+'">'+k.toUpperCase()+'</span></td><td>'+a.pose_mean_ms.toFixed(2)+' ms</td><td>'+a.cpu_mean_pct_machine.toFixed(1)+'%</td><td>'+a.ram_peak_mib.toFixed(0)+' MiB</td><td>'+a.gpu_peak_pct_device.toFixed(0)+'%</td><td>'+a.vram_peak_mib_device.toFixed(0)+' MiB</td></tr>'}).join('');document.querySelector('#res-sampling').textContent=r.sample_count+'개 실측 표본 · 기록 구간 '+r.sample_span_seconds.toFixed(1)+'초 · '+(ds==='REHAB26'?'51초 시험 영상의 관절 추출 실행 기록':'동일 시연 샘플을 독립 프로세스로 별도 재측정');document.querySelector('#res-raw').href=r.source}const beforeResourceUpdate=update;update=function(){beforeResourceUpdate();renderResources()};model.onchange=update;dataset.onchange=update;document.querySelector('#resource-metric').onchange=renderResources;renderResources();'''
js=js.replace('__DATA__',json.dumps(payload,ensure_ascii=False).replace('</','<\\/'))
page_path=ROOT/'selected-exercise.html';page=page_path.read_text()
# Re-running first removes the previous resource addition, keeping one dashboard.
page=re.sub(r'<section id="resource-dashboard".*?</section>','',page,flags=re.S)
page=re.sub(r'<script id="resource-script">.*?</script>','',page,flags=re.S)
page=re.sub(r'<style id="resource-style">.*?</style>','',page,flags=re.S)
page=page.replace('<section><h2 id="comparison-title">',section+'<section><h2 id="comparison-title">',1)
assert 'id="resource-dashboard"' in page
if 'id="resource-jump"' not in page:
 page=page.replace('<section><label>데이터셋', '<p id="resource-jump"><a href="#resource-dashboard">자원 사용량 · 그래프 보기 ↓</a></p><section><label>데이터셋',1)
page=page.replace('</html>','<style id="resource-style">'+css+'</style><script id="resource-script">'+js+'</script></html>')
page_path.write_text(page)
report=ROOT/'reports/2026-10-16-squat-correction-training.md';body=report.read_text();heading='## 10. 데이터셋·모델별 자원 시각화'
if heading in body:body=body[:body.index(heading)].rstrip()+'\n'
body+='\n'+heading+'\n\n선택한 데이터셋·추출기에 따라 CPU/RAM/GPU/VRAM 카드·시간 그래프·3모델 비교표를 갱신한다. REHAB26은 기존 교정 시연 추출 기록이고, QEVD와 Pose Comparison은 동일 샘플을 각 모델별 독립 프로세스에서 다시 측정했다. 그래프는 실시간 수치가 아닌 저장된 실행 기록이다.\n\n| 자료 | 모델 | CPU 평균(전체20코어) | RAM 최대 MiB | NVIDIA GPU 최대 | NVIDIA VRAM 최대 MiB | 표본 |\n|---|---|---:|---:|---:|---:|---:|\n'
for name,models in data.items():
 for m,r in models.items():body+=f"| {name} | {m} | {r['cpu_mean_pct_machine']:.1f}% | {r['ram_peak_mib']:.0f} | {r['gpu_peak_pct_device']:.0f}% | {r['vram_peak_mib_device']:.0f} | {r['sample_count']} |\n"
body+='\n프로세스 CPU 평균은 실행 프로세스 CPU 시간/프레임 처리 벽시계 시간으로 계산한 기존 지표를 20으로 나눴다. 시간 그래프는 약 0.5초 간격 표본이다. RAM은 프로세스 RSS, GPU/VRAM은 다른 앱을 포함한 장치 전체다. 교정 분류기 학습 및 브라우저 재생의 자원은 포함하지 않는다. 각 실행의 초기화·결과 저장·후처리 일부가 시간 그래프에 포함된다. 자료와 클립 길이가 다르므로 데이터셋 간 절대 수치의 우열로 해석하지 않는다.\n'
report.write_text(body)
print(json.dumps({'resource_combinations':sum(len(x) for x in data.values()),'summary':{ds:{m:round(r['ram_peak_mib']) for m,r in models.items()} for ds,models in data.items()}},ensure_ascii=False))
